"""Build 16 game hubs / 32 games; keep unit and catalogue discovery in sync."""
from pathlib import Path
import html,subprocess
from unit_games_integration import manifest,integrate,ROOT
E=html.escape
P='../../../../../'
def game_specs(u):
 return [('classic',u['classic'],'cards.html','cards-cover.svg'),('workshop',u['workshop'],'workshop.html','cover.svg')]+[(g['id'],g,g['file'],g['cover']) for g in u.get('extraGames',[])]
def round_count(u):
 return sum(len(g['rounds']) for _,g,_,_ in game_specs(u))


def shell(u,title,intro,body,mode=''):
 subject={'maths':'Maths','physics':'Physics','chemistry':'Chemistry'}[u['subject']];course=u['year'].upper()+' '+subject
 attrs=f'data-unit="{u["id"]}" data-mode="{mode}"' if mode else ''
 extra=next((g for g in u.get('extraGames',[]) if g['id']==mode),None)
 js=(f'<script type="module" src="{P}assets/unit-games/algebra-games.js?v=1"></script><link rel="stylesheet" href="{P}assets/unit-games/algebra-games.css?v=1">' if extra else f'<script type="module" src="{P}assets/unit-games/games.js?v={"plain-term-markers-1" if u["id"]=="brackets" else "1"}"></script>') if mode else ''
 tabs=''.join(f'<a href="{href}"'+(' aria-current="page"' if mode==key else '')+f'>{j+1:02} · {E(g["title"])}</a>' for j,(key,g,href,_) in enumerate(game_specs(u)))
 hero_art=extra['cover'] if extra else 'cover.svg'
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f7f8fc"><title>{E(title)} | {E(course)} | Learning Lab</title><meta name="description" content="{E(intro)}"><link rel="icon" type="image/png" href="{P}assets/brand/learning-lab-logo.png"><link rel="stylesheet" href="{P}platform.css"><link rel="stylesheet" href="{P}assets/brand/brand.css?v=1"><link rel="stylesheet" href="{P}assets/unit-games/games.css?v=1"><link rel="stylesheet" href="{P}assets/desktop-layout.css?v=desktop-1">{js}</head><body {attrs}><a class="skip-link" href="#main">Skip to game</a><header class="site-header"><a class="wordmark" href="{P}index.html"><img class="brand-logo" src="{P}assets/brand/learning-lab-logo.png" width="46" height="46" alt=""><span>learning<span class="wordmark-light">lab</span><small>A PLACE FOR CURIOUS MINDS</small></span></a><nav aria-label="Main navigation"><a href="../index.html">{E(u['name'])} lesson</a><a href="./">Games</a><a href="../revision.html">Revision simulator</a></nav></header><main id="main" tabindex="-1"><nav class="breadcrumbs" aria-label="Breadcrumb"><ol><li><a href="{P}index.html#/years/{u['year']}/{u['subject']}">{E(course)}</a></li><li><a href="../index.html">{E(u['name'])}</a></li><li><a href="./">Games</a></li><li><span aria-current="page">{E(title)}</span></li></ol></nav><section class="play-hero"><div><span class="play-tag">{E(course.upper())} · LEARN THROUGH PLAY</span><h1>{E(title)}</h1><p>{E(intro)}</p><nav class="play-tabs" aria-label="Choose a game">{tabs}</nav></div><img src="{hero_art}" width="800" height="360" alt="{E(u['name'])} illustrated game board"></section>{body}<p class="play-note">Practice games: your score stays on this page and is not sent to the teacher dashboard. For a recorded Test yourself quiz, use the <a href="../revision.html">revision simulator</a>.</p><noscript><p class="play-panel">Enable JavaScript to play. The <a href="../index.html">unit lesson</a> remains available.</p></noscript></main><footer class="site-footer"><a class="footer-brand" href="{P}index.html"><img class="brand-logo" src="{P}assets/brand/learning-lab-logo.png" width="34" height="34" alt="">learning<span>lab</span></a><p>Think. Build. Explain. Try again.</p><a href="{P}activities/games/">All learning games &amp; references →</a></footer></body></html>'''

for u in manifest():
 folder=ROOT/u['path']/'games';folder.mkdir(parents=True,exist_ok=True)
 cards=''
 for key,g,href,cover in game_specs(u):
  if u['id']=='brackets' and key=='classic':cover+='?v=plain-term-markers-1'
  cards+=f'<a class="play-hub-card" href="{href}"><img src="{cover}" width="800" height="360" alt=""><div><span class="play-tag">{"CARD CHALLENGE" if key=="classic" else "BUILD & SOLVE"}</span><h2>{E(g["title"])}</h2><p>{E(g["intro"])}</p><strong>Play {"three rounds" if len(g["rounds"])==3 else "six missions"} →</strong></div></a>'
 body=f'<section class="play-panel"><h2>How to play</h2><div class="games-help-grid"><div><b><span>1</span>Make a move</b><p>Drag a card or select it and click its destination. In the workshop, use the controls on the game bench.</p></div><div><b><span>2</span>Try your model</b><p>Check your board or run the apparatus. Use the picture and reading to see what changed.</p></div><div><b><span>3</span>Learn and retry</b><p>Read the explanation. Ask for a hint or reveal a solution, then revisit tricky rounds at the end.</p></div></div></section><div class="game-hub-grid">{cards}</div>'
 if u.get('extraGames'):
  refs={source['url']:source['label'] for g in u['extraGames'] for source in g['sources']}
  body+='<details id="new-game-references" class="play-panel"><summary>Game inspiration and further exploration</summary><p>These are original Learning Lab adaptations of documented PhET activity patterns. The numerical challenges, robot crew model and illustrations were created for this unit. Historical public documentation was consulted on 29 October 2026; live PhET, NRICH and Transum pages were blocked in the research environment.</p><ul>'+''.join(f'<li><a href="{E(url)}" target="_blank" rel="noopener noreferrer">{E(label)}</a></li>' for url,label in refs.items())+'</ul></details>'
 intro='Two ways to play with this unit: a card challenge and an interactive puzzle. Take your time, use the hints and explain your model.' if not u.get('extraGames') else 'Four ways to explore algebra: match rules, plot coordinates, decode mystery machines and run a proportion paintworks. Take your time, use the hints and explain your model.'
 (folder/'index.html').write_text(shell(u,u['name']+' Games',intro,body))
 for key,g,href,_ in game_specs(u):
  (folder/href).write_text(shell(u,g['title'],g['intro'],'<div id="game-app"><p role="status">Preparing your game board…</p></div>',key))
subprocess.run(['node','--input-type=module','-e',"""import {writeFileSync} from 'node:fs';import {units} from './assets/unit-games/data.mjs';import {scene,classicCover} from './assets/unit-games/art.mjs';import {machineArt,paintArt} from './assets/unit-games/algebra-art.mjs';import {initialWorkshop} from './assets/unit-games/models.mjs';for(const u of units){const g=u.workshop;let s=initialWorkshop(g.kind);if(g.kind==='pizza')s.slices=[0,1,2,3,4,5,6,7,8];if(g.kind==='molecule'){s.carbons=4;s.bonds=[2,1,2];}writeFileSync(u.path+'games/cover.svg',scene(g.kind,g.rounds[0].params,s));writeFileSync(u.path+'games/cards-cover.svg',classicCover(u));for(const extra of u.extraGames||[]){const r=extra.rounds[0];writeFileSync(u.path+'games/'+extra.cover,extra.id==='machine'?machineArt({x:3,y:'?' }):paintArt(r,{blue:3,gold:6,robots:1,minutes:1},'mix',1));}}"""],cwd=ROOT,check=True)
directory=ROOT/'activities/games';directory.mkdir(parents=True,exist_ok=True)
P0='../../'
groups=''
for year,subject,label in [('y7','maths','Year 7 Maths'),('y10','physics','Year 10 Physics'),('y10','chemistry','Year 10 Chemistry')]:
 links=''.join(f'<a class="play-hub-card" href="{P0}{u["path"]}games/"><img src="{P0}{u["path"]}games/cover.svg" width="800" height="360" alt=""><div><span class="play-tag">{len(game_specs(u))} GAMES · {round_count(u)} ROUNDS</span><h3>{E(u["name"])}</h3><p>{'<br>'.join(E(g['title']) for _,g,_,_ in game_specs(u))}</p><strong>Choose a game →</strong></div></a>' for u in manifest() if u['year']==year and u['subject']==subject)
 groups+=f'<section id="{subject}" class="play-panel"><h2>{label}</h2><div class="game-hub-grid">{links}</div></section>'
references='''<section id="references" class="play-panel"><h2>Game ideas and online references</h2><p>These games combine familiar classroom formats—24, matching pairs, card sorts and ordering—with original Learning Lab target puzzles. The pictures, challenges, explanations and code here were created for this platform.</p><p>Related PhET resources are listed below for further exploration. Their public GitHub documentation was consulted on 29 October 2026. The repository front pages now describe a move to a monorepo; these are historical references. Live PhET pages, NRICH, Transum and RSC could not be checked from this environment. No external game is embedded or required to play.</p><div class="source-links"><a href="https://phet.colorado.edu/" target="_blank" rel="noopener noreferrer">PhET simulations ↗</a></div><ul><li><a href="https://github.com/phetsims/area-builder/blob/main/doc/model.md" target="_blank" rel="noopener noreferrer">Area Builder: area and perimeter targets</a> — Geometry I.</li><li><a href="https://github.com/phetsims/number-line-integers/blob/main/doc/model.md" target="_blank" rel="noopener noreferrer">Number Line: Integers: comparing signed positions</a> — Numbers II.</li><li><a href="https://github.com/phetsims/expression-exchange/blob/main/doc/model.md" target="_blank" rel="noopener noreferrer">Expression Exchange: build expressions to match targets</a> — Boxes &amp; Brackets.</li><li><a href="https://github.com/phetsims/proportion-playground/blob/main/doc/model.md" target="_blank" rel="noopener noreferrer">Proportion Playground: bead, paint and billiards models</a> — Algebra I and Numbers III.</li><li><a href="https://github.com/phetsims/fractions-common/blob/main/doc/model.md" target="_blank" rel="noopener noreferrer">Fractions Suite: matching and building games</a> — Numbers III.</li><li><a href="https://github.com/phetsims/fractions-equality/blob/main/doc/model.md" target="_blank" rel="noopener noreferrer">Fractions: Equality: equivalent representations</a> — Numbers III.</li><li><a href="https://github.com/phetsims/graphing-lines/blob/main/doc/model.md" target="_blank" rel="noopener noreferrer">Graphing Lines: relating equations and graphs</a> — Algebra I.</li><li><a href="https://github.com/phetsims/wave-on-a-string/blob/main/doc/model.md" target="_blank" rel="noopener noreferrer">Wave on a String: frequency, amplitude and travelling waves</a> — Waves.</li><li><a href="https://github.com/phetsims/forces-and-motion-basics/blob/main/doc/model.md" target="_blank" rel="noopener noreferrer">Forces and Motion: Basics: net force and motion</a> — Dynamics and motion.</li><li><a href="https://github.com/phetsims/ohms-law" target="_blank" rel="noopener noreferrer">Ohm’s Law</a>, <a href="https://github.com/phetsims/bending-light" target="_blank" rel="noopener noreferrer">Bending Light</a> and <a href="https://github.com/phetsims/energy-forms-and-changes" target="_blank" rel="noopener noreferrer">Energy Forms and Changes</a> — related electricity, optics and thermal resources.</li><li><a href="https://github.com/phetsims/acid-base-solutions/blob/main/doc/model.md" target="_blank" rel="noopener noreferrer">Acid-Base Solutions: strength and concentration models</a> — Acids and Bases.</li><li><a href="https://github.com/phetsims/balancing-chemical-equations/blob/main/doc/model.md" target="_blank" rel="noopener noreferrer">Balancing Chemical Equations: conservation puzzles</a> — Redox and organic reaction balances.</li><li><a href="https://github.com/phetsims/build-a-molecule/blob/main/doc/model.md" target="_blank" rel="noopener noreferrer">Build a Molecule: constructing molecules</a> — Organic Chemistry.</li></ul><p>Factor sorting, signed-number ordering, like-term sorting and reactivity ladders use familiar classroom game structures. The rover, bag factory, displacement vault, electron-delivery challenge and diene balance are original topic-specific designs, not claims of an official PhET game or a globally new invention.</p></section>'''
(directory/'index.html').write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Learning Games | Learning Lab</title><link rel="icon" href="{P0}assets/brand/learning-lab-logo.png"><link rel="stylesheet" href="{P0}platform.css"><link rel="stylesheet" href="{P0}assets/brand/brand.css?v=1"><link rel="stylesheet" href="{P0}assets/unit-games/games.css?v=1"><link rel="stylesheet" href="{P0}assets/desktop-layout.css?v=desktop-1"></head><body><a class="skip-link" href="#main">Skip to games</a><header class="site-header"><a class="wordmark" href="{P0}index.html"><img class="brand-logo" src="{P0}assets/brand/learning-lab-logo.png" width="46" height="46" alt=""><span>learning<span class="wordmark-light">lab</span></span></a><nav aria-label="Main navigation"><a href="{P0}index.html#/years">Years and subjects</a><a href="#references">Game references</a></nav></header><main id="main" tabindex="-1"><section class="play-hero"><div><span class="play-tag">34 GAMES · 16 UNITS · 108 ROUNDS</span><h1>Learn through play.</h1><p>Move a card. Build a model. Test an idea. Find games for Y7 Maths and Y10 Physics and Chemistry, with hints, explanations and a chance to try again.</p><nav class="play-tabs" aria-label="Choose a subject"><a href="#maths">Y7 Maths</a><a href="#physics">Y10 Physics</a><a href="#chemistry">Y10 Chemistry</a></nav></div><img src="../y10/chemistry/organic-chemistry/games/cover.svg" width="800" height="360" alt="Colourful carbon-chain game"></section>{groups}{references}<p class="play-note">Game scores stay on the page. Only the separate revision simulator’s Test yourself mode can submit results to the teacher dashboard.</p></main><footer class="site-footer"><a href="{P0}index.html">Learning Lab</a><p>Computer-first games · Mouse and keyboard</p><a href="{P0}index.html#/years">Explore all activities →</a></footer></body></html>''')
integrate()
print('Built 16 hubs, 34 games and original SVG covers; integrated all unit pages and catalogue links.')
